"""Paint-only caption regression, using compiled Cast templates in Chromium."""
from pathlib import Path
from playwright.sync_api import sync_playwright
import base64, re
ROOT=Path(__file__).resolve().parents[1]
JS=(ROOT/'dist/frontend.js').read_text('utf8').rsplit('export {',1)[0].replace('export function ', 'function ')+'\nwindow.t={CAST_PRESENTATION_ENTRIES,CAST_PRESENTATION_CSS,CAST_PRESENTATION_SIDE_CSS,castPresentationTemplate};'
ART='data:image/png;base64,'+base64.b64encode((ROOT/'tests/fixtures/cast-portrait.png').read_bytes()).decode()
WORLD=base64.b64decode(re.search(r'--world:\s*url\("data:image/jpeg;base64,([^"\)]+)"\)',(ROOT/'docs/cast-layout-sources/curated-cards.html').read_text('utf8'))[1])
with sync_playwright() as p:
    browser=p.chromium.launch(executable_path='/usr/bin/chromium',headless=True,args=['--no-sandbox'])
    page=browser.new_page(viewport={'width':1160,'height':850})
    page.route('**/api/v1/images/world1',lambda route:route.fulfill(content_type='image/jpeg',body=WORLD))
    page.set_content('<!doctype html><html><head><base href="http://cast.local/"></head><body style="margin:0;background:#15131a;color:#eee;font:14px system-ui"><main id="root"></main></body></html>')
    page.add_script_tag(content=JS)
    page.evaluate('''()=>{const marker='/* Open-caption readability (1.0.53)';const [before,after]=t.CAST_PRESENTATION_CSS.split(marker);if(!after)throw Error('Missing caption paint');const base=document.createElement('style');base.textContent=before+'\\n'+t.CAST_PRESENTATION_SIDE_CSS;document.head.append(base);window.paint=document.createElement('style');paint.textContent=marker+after;document.head.append(paint);window.make=(id,side,color,art)=>t.castPresentationTemplate(id,{key:'speaker-neutral',src:art,name:'Speaker',label:'neutral',dialogue:'“Tell Yaoyorozu she owes five thousand yen. You dropped that straight into Mina’s lap like you were handing her a press release. Half of our old class is going to be losing their minds before we even get out of boots.”',color,side,background:{id:'world1',name:'Evening walkway'},crop:{enabled:false,x:50,y:20,zoom:1}},s=>s)}''')
    result=page.evaluate('''async art=>{const targeted=new Set(['vn-hero','afterglow-cinema','afterglow-letterbox','rainbound-platform','memory-filmstrip','overlap-materia','overlap-cinema']);const errors=[];let count=0;for(const e of t.CAST_PRESENTATION_ENTRIES.filter(x=>x.origin==='atelier'))for(const width of [520,320])for(const side of ['auto','left','right'])for(const color of ['','#ffcc00','#221122']){const root=document.querySelector('#root');root.style.width=width+'px';root.innerHTML=make(e.id,side,color,art);await root.querySelector('img').decode();const els=[...root.querySelectorAll('*')],q=root.querySelector('[data-swarm-cast-dialogue]'),i=els.indexOf(q);const snapshot=()=>els.map(el=>{const c=getComputedStyle(el),r=el.getBoundingClientRect();return {rect:[r.x,r.y,r.width,r.height],color:c.color,background:c.background,boxShadow:c.boxShadow,font:c.font,transform:c.transform,shadow:c.textShadow}});paint.sheet.disabled=true;const before=snapshot();paint.sheet.disabled=false;const after=snapshot();for(let j=0;j<els.length;j++){const {shadow:a,...x}=before[j],{shadow:b,...y}=after[j];if(JSON.stringify(x)!==JSON.stringify(y))errors.push([e.id,width,side,color,'non-shadow change',j]);}const should=targeted.has(e.id)&&color!=='#221122';if(should&&(after[i].shadow===before[i].shadow||after[i].shadow.split('rgba(').length!==4))errors.push([e.id,width,side,color,'missing tight shadow',after[i].shadow]);if(!should&&after[i].shadow!==before[i].shadow)errors.push([e.id,width,side,color,'unexpected dialogue shadow',after[i].shadow]);count++;}return {count,errors}}''',ART)
    assert not result['errors'],result['errors'][:15]
    assert result['count']==360
    page.evaluate('''art=>{const root=document.querySelector('#root');root.style.width='auto';root.innerHTML=`<div style="padding:16px;display:grid;gap:12px"><h1 style="font-size:20px;margin:0">Caption readability · same geometry, same ink</h1>${['afterglow-cinema','vn-hero','overlap-materia'].map(id=>`<section><h2 style="font-size:14px">${t.CAST_PRESENTATION_ENTRIES.find(e=>e.id===id).name}</h2><div style="display:grid;grid-template-columns:1fr 1fr;gap:12px"><div id="before-${id}"><small>BEFORE</small>${make(id,'right','#ffcc00',art)}</div><div><small>AFTER</small>${make(id,'right','#ffcc00',art)}</div></div></section>`).join('')}</div>`;paint.sheet.disabled=true;const prior=[...root.querySelectorAll('[id^="before-"] *')].map(el=>[el,getComputedStyle(el).textShadow]);paint.sheet.disabled=false;for(const [el,shadow] of prior)el.style.textShadow=shadow;}''',ART)
    page.wait_for_function('[...document.images].every(i=>i.complete)')
    out=ROOT/'test-results/cast-caption-readability.png';out.parent.mkdir(exist_ok=True)
    page.screenshot(path=str(out),full_page=True)
    print(f'CAST CAPTION READABILITY PASS: {result["count"]} cases; authored ink, material and layout unchanged; only selected dialogue shadows change')
    browser.close()
